t=Table(rows,colWidths=[85*mm,32*mm,45*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eaf2e5')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,-1),.3,colors.HexColor('#c8d7dc'))]));story+=[t,Spacer(1,8),p('Unity-import, Animator-bindinger, materialer/normaler, shaders og faktisk billedkvalitet er endnu ikke verificeret. Roughness-/nummer-/handsketeksturer er bevaret, men ikke alle er færdigt mappet til native URP-kanaler. Det er stadig de eksisterende 12 klip; motion matching og fuld fod-IK er ikke implementeret.'),h('Vigtigste mapper'),p('Core: Math2, ClubRules, MatchState, BallPhysics, MatchSimulation, SaveStore og SaveWriter. Runtime: TouchlineBootstrap, TouchlineUI, MatchInputRouter, FootballWorld, PlayerView, BroadcastCamera, MatchAudio og UnityCodec. Editor: importregler, URP/materialer/Animator og Android-build. Hertil scene, pakker, 31 ressourcer, fem FBX, NUnit-/standalone-tests, værktøjer og evidens.'),p('Komplet filliste: unity/Evidence/files.txt. Detaljer: unity/README.md.','TLSmall'),PageBreak(),p('Åbning, Android og næste skridt','TLTitle'),h('Sådan åbnes projektet'),p('Unity Hub → installer 6000.6.10f1 med Android Build Support, Android SDK & NDK Tools og OpenJDK. Åbn unity/TouchlineUnity. Lad pakker/import blive færdige; menuen Touchline → Klargør Unity-projekt opretter URP, materialer og controllere. Genstart editoren, hvis input-backends kræver det. Åbn Assets/Touchline/Scenes/Touchline.unity og tryk Play. Kør Unity EditMode-tests og ret alle reelle konsolfejl før aflevering.'),h('Hvad der konkret blokerer en Unity-APK'),p('Unity Editor findes ikke her. Den ønskede editor kræver 9,13 GB installeret plads, før Android-moduler; tilgængelig plads er utilstrækkelig. Unity-buildaktivering er ikke til rådighed i værktøjerne. En separat C#-kompiler er installeret isoleret og brugt til domænetests, men kan ikke erstatte Unity Editor/IL2CPP.'),p('Ingen Unity-APK eller fysisk installation er gennemført. CPU/GPU-frame time, touchlatens, 60/120 FPS, RAM, varme og batteri på OnePlus Nord 4 er ikke målt. Den tidligere TEST59-APK er bevaret og downloadverificeret særskilt; den er stadig Capacitor og må ikke forveksles med Unity.'),h('Når et Unity-buildmiljø er tilgængeligt'),p('Menuen Touchline → Byg separat Android-test-APK bygger ARM64/IL2CPP til Builds/Android/Touchline-Unity-0.1.0.apk. Ny identitet: dk.touchline.footballidle.unitytest. Ingen gamle keystores åbnes. En vedvarende, sikker Unity-testsigneringsidentitet skal etableres før efterfølgende installerbare Unity-opdateringer.'),h('Fem minutter på telefonen efter første rigtige build'),p('1. Koldstart og dansk klubflow. 2. Midterplet, fløjt og kort første aflevering. 3. Styrepude + sprint med to fingre, 90/180 graders vending, aflevering/stikning/skud. 4. Mute og baggrund/retur; ingen gammel lyd eller fast input. 5. Tilbage til portrætmenu og genstart med samme lokale Unity-klub. Profilér derefter en længere kamp på den fysiske enhed.'),h('Størst reel fremgang næste runde'),p('Først: reel Unity-import, API-/shader-/Animator-kontrol, PlayMode/EditMode og første Unity-APK. Derefter fysisk profilerdata og kampfølelse på OnePlus Nord 4. Så en versionsstyret backend-/dataadapter og testmigration, efterfulgt af systematisk overførsel af klub, karriere, marked, liga/Europa og flere kampregler. Ingen produktionstilslutning eller udgivelse uden særskilt godkendelse.')]
